/*
 *  오늘 이후 날자 체크
 *  obj : 오늘 이후 날자인지 체크할 일자
 */
/**
 * @method
 * @name fn_chkToday
 * @description desc
 * @param {string} obj desc
 * @param {string} objNm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkToday = function(obj, objNm) {
    var today = new Date();
    var nowYear = today.getYear();
    var nowMonth = today.getMonth() + 1;
    var nowDate = today.getDate();
    if (nowMonth < 10) {
        nowMonth = "0" + nowMonth;
    }
    if (parseInt(nowDate) < 10) {
        nowDate = "0" + nowDate;
    }
    var toDd = nowYear + '' + nowMonth + '' + nowDate;
    if (parseInt(toDd) >= parseInt(obj.getText())) {
        alert("[" + objNm + "]" + obj.getText() + " : 오늘 이후의 일자를 입력하세요.");
        return false;
    }
    return true;
};


/*
 *  날짜 비교 
 *  obj1 : 빠른 날자
 *  obj2 : 늦은 날자 
 */
/**
 * @method
 * @name fn_chkDateCompare
 * @description desc
 * @param {string} obj1 desc
 * @param {string} obj2 desc
 * @param {string} objNm1 desc
 * @param {string} objNm2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkDateCompare = function(obj1, obj2, objNm1, objNm2) {
    if (parseInt(obj1.getText()) > parseInt(obj2.getText())) {
        alert(objNm1 + "(" + obj1.getText() + ")은 " + objNm2 + "(" + obj2.getText() + ") 보다 이전 일자입니다.");
        return false;
    }
    return true;
};



