/**
 * 신규상장시 분배기준일정보를 입력하기 위해 데이타 셋을 갯수만큼 초기화함
 */
/**
 * @method
 * @name fn_initDistrPayGridData
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} initYn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_initDistrPayGridData = function(dtsObj, initYn) {
    if (initYn == "N") {
        var vdtsDistrPayrowCnt = dtsObj.getTotalRow();
        for (i = vdtsDistrPayrowCnt; i < 12; i++) {
            dtsObj.AddRow();
        }
    } else if (initYn == "Y") {
        for (j = 0; j < 12; j++) {
            dtsObj.AddRow();
        }
    }
    dtsObj.setFocusedCell(1, 0);
};



/**
 * 신규상장시 LP정보를 입력하기 위해 데이타 셋을 갯수만큼 초기화함
